    if date_ranges is None:
        return 0

    # Convert every range to pandas Timestamps, skipping empty/invalid ranges.
    parsed = []
    for date_range in date_ranges:
        if not date_range:
            continue
        start, end = date_range
        start = pd.Timestamp(start).normalize()
        end = pd.Timestamp(end).normalize()
        if start > end:
            # Ignore (or swap) inverted ranges -> contribute 0 days
            continue
        parsed.append((start, end))

    if not parsed:
        return 0

    # Collect all years covered so holidays are fetched once per year.
    years = set()
    for start, end in parsed:
