    try:
        country_holidays = holidays_lib.country_holidays(country, years=sorted(years))
    except (KeyError, AttributeError, NotImplementedError):
        country_holidays = []
    holiday_list = list(country_holidays)

    total = 0
    for start, end in parsed:
        bdays = pd.bdate_range(start=start, end=end, holidays=holiday_list)
        total += len(bdays)

    return int(total)


